pm.test("Statut 200", () => {
    pm.response.to.have.status(200);
});

pm.test("La réponse est un tableau", () => {
    pm.expect(pm.response.json()).to.be.an("array");
});

pm.test("Statut 404", () => {
    pm.response.to.have.status(404);
});

pm.test("Erreur métier lisible", () => {
    const body = pm.response.json();
    pm.expect(body.statut).to.eql(404);
    pm.expect(body.message).to.include("9999");
    pm.expect(body.horodatage).to.be.a("string");
});

pm.test("Statut 201", () => {
    pm.response.to.have.status(201);
});

pm.test("Identifiant généré", () => {
    const body = pm.response.json();
    pm.expect(body.idContrat).to.be.a("number");
    pm.environment.set("contratId", body.idContrat);
});

pm.test("Statut 201", () => {
    pm.response.to.have.status(201);
});

pm.test("Deux paiements créés avec leurs identifiants", () => {
    const body = pm.response.json();

    pm.expect(body.idContrat).to.be.a("number");
    pm.expect(body.paiements).to.have.lengthOf(2);

    body.paiements.forEach(paiement => {
        pm.expect(paiement.idPaiement).to.be.a("number");
    });

    pm.environment.set("contratId", body.idContrat);
    pm.environment.set("paiementId", body.paiements[0].idPaiement);
});
